/* 切换从设备时先复位再重配 */
SPI_I2S_DeInit(SPI1);
SPI_Init(SPI1, &SPI_InitStructure);
SPI_Cmd(SPI1, ENABLE);

SPI_InitTypeDef SPI_InitStructure;
GPIO_InitTypeDef GPIO_InitStructure;

/* SPI1 在 APB2，SPI2 在 APB1，两个时钟函数不一样 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_SPI1, ENABLE);

/* SCK=PA5, MISO=PA6, MOSI=PA7 必须配成复用推挽 */
GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_5 | GPIO_Pin_6 | GPIO_Pin_7;
GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_AF_PP;
GPIO_Init(GPIOA, &GPIO_InitStructure);

/* 软件 NSS：片选自己用一个普通 GPIO 控制，这里配成推挽输出 */
GPIO_InitStructure.GPIO_Pin  = GPIO_Pin_4;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_PP;
GPIO_Init(GPIOA, &GPIO_InitStructure);
GPIO_SetBits(GPIOA, GPIO_Pin_4);

SPI_StructInit(&SPI_InitStructure);
SPI_InitStructure.SPI_Direction         = SPI_Direction_2Lines_FullDuplex;
SPI_InitStructure.SPI_Mode              = SPI_Mode_Master;
SPI_InitStructure.SPI_DataSize          = SPI_DataSize_8b;
SPI_InitStructure.SPI_CPOL              = SPI_CPOL_Low;    /* Mode 0 */
SPI_InitStructure.SPI_CPHA              = SPI_CPHA_1Edge;   /* Mode 0 */
SPI_InitStructure.SPI_NSS               = SPI_NSS_Soft;
SPI_InitStructure.SPI_BaudRatePrescaler = SPI_BaudRatePrescaler_8; /* 72/8 = 9MHz */
SPI_InitStructure.SPI_FirstBit          = SPI_FirstBit_MSB;
SPI_InitStructure.SPI_CRCPolynomial     = 7;
SPI_Init(SPI1, &SPI_InitStructure);

SPI_Cmd(SPI1, ENABLE);   /* 不使能则收发毫无反应 */

I2S_InitTypeDef I2S_InitStructure;

/* 注意时钟函数：SPI2/I2S2 在 APB1 上 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_SPI2, ENABLE);

/* PB12=WS PB13=CK PB15=SD PC6=MCK，全部配成复用推挽 */
GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_12 | GPIO_Pin_13 | GPIO_Pin_15;
GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_AF_PP;
GPIO_Init(GPIOB, &GPIO_InitStructure);

I2S_StructInit(&I2S_InitStructure);
I2S_InitStructure.I2S_Mode         = I2S_Mode_MasterTx;
I2S_InitStructure.I2S_Standard     = I2S_Standard_Phillips;
I2S_InitStructure.I2S_DataFormat   = I2S_DataFormat_16b;
I2S_InitStructure.I2S_MCLKOutput   = I2S_MCLKOutput_Enable;
I2S_InitStructure.I2S_AudioFreq    = I2S_AudioFreq_44k;
I2S_InitStructure.I2S_CPOL         = I2S_CPOL_Low;
I2S_Init(SPI2, &I2S_InitStructure);

I2S_Cmd(SPI2, ENABLE);

SPI_InitTypeDef SPI_InitStructure;

SPI_StructInit(&SPI_InitStructure);          /* 先拿默认值 */
SPI_InitStructure.SPI_Mode = SPI_Mode_Master; /* 默认是从机，主机必须改 */
SPI_InitStructure.SPI_BaudRatePrescaler = SPI_BaudRatePrescaler_8;
SPI_Init(SPI1, &SPI_InitStructure);

I2S_InitTypeDef I2S_InitStructure;

I2S_StructInit(&I2S_InitStructure);
I2S_InitStructure.I2S_Mode       = I2S_Mode_MasterTx;   /* 默认 SlaveTx，主机要改 */
I2S_InitStructure.I2S_AudioFreq  = I2S_AudioFreq_44k;
I2S_InitStructure.I2S_MCLKOutput = I2S_MCLKOutput_Enable;
I2S_Init(SPI2, &I2S_InitStructure);

SPI_Cmd(SPI1, ENABLE);

/* 发送一个字节并等待完成 */
SPI_I2S_SendData(SPI1, 0x9F);
while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_TXE) == RESET) { }
while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_BSY) == SET) { }

I2S_Cmd(SPI2, ENABLE);

/* 之后用 SPI_I2S_SendData 推音频数据，注意 I2S 下这个函数名仍是 SPI_ 前缀 */
SPI_I2S_SendData(SPI2, pcmSample);

SPI_I2S_ITConfig(SPI1, SPI_I2S_IT_RXNE, ENABLE);

NVIC_InitStructure.NVIC_IRQChannel = SPI1_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 0x02;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0x02;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

void SPI1_IRQHandler(void)
{
  if (SPI_I2S_GetITStatus(SPI1, SPI_I2S_IT_RXNE) != RESET)
  {
    /* 读 DR 顺带清 RXNE 标志，不需要再调 ClearITPendingBit */
    rxByte = SPI_I2S_ReceiveData(SPI1);
  }
}

DMA_InitTypeDef DMA_InitStructure;

RCC_AHBPeriphClockCmd(RCC_AHBPeriph_DMA1, ENABLE);

/* SPI1_TX 固定映射到 DMA1_Channel3 */
DMA_DeInit(DMA1_Channel3);
DMA_InitStructure.DMA_PeripheralBaseAddr = (uint32_t)&SPI1->DR;
DMA_InitStructure.DMA_MemoryBaseAddr     = (uint32_t)txBuf;
DMA_InitStructure.DMA_DIR                = DMA_DIR_PeripheralDST;   /* 内存 -> 外设 */
DMA_InitStructure.DMA_BufferSize         = 512;
DMA_InitStructure.DMA_PeripheralInc      = DMA_PeripheralInc_Disable;
DMA_InitStructure.DMA_MemoryInc          = DMA_MemoryInc_Enable;
DMA_InitStructure.DMA_PeripheralDataSize = DMA_PeripheralDataSize_Byte;
DMA_InitStructure.DMA_MemoryDataSize     = DMA_MemoryDataSize_Byte;
DMA_InitStructure.DMA_Mode               = DMA_Mode_Normal;
DMA_InitStructure.DMA_Priority           = DMA_Priority_High;
DMA_InitStructure.DMA_M2M                = DMA_M2M_Disable;
DMA_Init(DMA1_Channel3, &DMA_InitStructure);

SPI_I2S_DMACmd(SPI1, SPI_I2S_DMAReq_Tx, ENABLE);
DMA_Cmd(DMA1_Channel3, ENABLE);

/* 主机全双工：发一个字节同时收回一个字节 */
uint8_t SPI1_ReadWriteByte(uint8_t txData)
{
  /* 1. 等发送缓冲区空 */
  while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_TXE) == RESET) { }

  /* 2. 写入要发的数据 */
  SPI_I2S_SendData(SPI1, txData);

  /* 3. 等接收缓冲区非空（全双工下收一个字节就等于发一个字节完成） */
  while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_RXNE) == RESET) { }

  /* 4. 读回数据兼清 RXNE */
  return (uint8_t)SPI_I2S_ReceiveData(SPI1);
}

/* 只写不读的场景（如驱动只写屏幕）：收尾要等 BSY 清零 */
SPI_I2S_SendData(SPI1, 0xA5);
while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_BSY) == SET) { }

/* 从 SPI Flash 读一个字节（主机发 0xFF 产生时钟） */
uint8_t SPI1_ReadByte(void)
{
  while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_TXE) == RESET) { }
  SPI_I2S_SendData(SPI1, 0xFF);

  while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_RXNE) == RESET) { }
  return (uint8_t)SPI_I2S_ReceiveData(SPI1);   /* 读 DR 同时清 RXNE */
}

/* 软件 NSS 且保持主机身份（多主机系统里没被选中时用这个） */
SPI_InitStructure.SPI_NSS = SPI_NSS_Soft;
SPI_Init(SPI1, &SPI_InitStructure);
SPI_Cmd(SPI1, ENABLE);

SPI_NSSInternalSoftwareConfig(SPI1, SPI_NSSInternalSoft_Set);

/* 只有主机 + 硬件 NSS 时才这么用，普通工程请用 GPIO 手动片选 */
SPI_InitStructure.SPI_Mode = SPI_Mode_Master;
SPI_InitStructure.SPI_NSS  = SPI_NSS_Hard;
SPI_Init(SPI1, &SPI_InitStructure);
SPI_SSOutputCmd(SPI1, ENABLE);
SPI_Cmd(SPI1, ENABLE);

/* 8 位发命令，再切 16 位发数据（如某些 LCD / ADC） */
SPI_I2S_SendData(SPI1, 0x02);
while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_BSY) == SET) { }

SPI_Cmd(SPI1, DISABLE);                      /* 必须先关 SPI */
SPI_DataSizeConfig(SPI1, SPI_DataSize_16b);
SPI_Cmd(SPI1, ENABLE);                       /* 重开才能生效 */

SPI_I2S_SendData(SPI1, 0x1234);

/* 使能 CRC 计算，发完数据后手动发 CRC */
SPI_CalculateCRC(SPI1, ENABLE);

/* ... 发送数据帧 ... */
while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_BSY) == SET) { }

SPI_TransmitCRC(SPI1);   /* 把 TXCRCR 的 CRC 值送上总线 */

/* 使能 CRC 计算，读出接收侧的 CRC 与本地比对 */
SPI_CalculateCRC(SPI1, ENABLE);

/* ... 收发数据 ... */

uint16_t rxCrc = SPI_GetCRC(SPI1, SPI_CRC_Rx);
if (rxCrc != expectedCrc) { /* 校验失败 */ }

uint16_t txCrc = SPI_GetCRC(SPI1, SPI_CRC_Tx);
uint16_t rxCrc = SPI_GetCRC(SPI1, SPI_CRC_Rx);

if (rxCrc != txCrc) { /* CRC 不匹配，数据在传输中被破坏 */ }

/* 确认多项式是否真的写进去了 */
if (SPI_GetCRCPolynomial(SPI1) != 7)
{
  /* 配置没生效，检查 SPI_Init 的 SPI_CRCPolynomial 字段 */
}

/* 单线半双工：先发命令，再切接收 */
SPI_InitStructure.SPI_Direction = SPI_Direction_1Line_Tx;
SPI_Init(SPI1, &SPI_InitStructure);
SPI_Cmd(SPI1, ENABLE);

SPI_I2S_SendData(SPI1, 0x9F);                     /* 发读 ID 命令 */
while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_BSY) == SET) { }

SPI_BiDirectionalLineConfig(SPI1, SPI_Direction_Rx);  /* 切到接收 */
while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_RXNE) == RESET) { }
id = SPI_I2S_ReceiveData(SPI1);

/* 通用收发一个字节 */
uint8_t SPI1_SwapByte(uint8_t tx)
{
  while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_TXE) == RESET) { }
  SPI_I2S_SendData(SPI1, tx);
  while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_RXNE) == RESET) { }
  return (uint8_t)SPI_I2S_ReceiveData(SPI1);
}

/* 一帧发完再拉高片选 */
while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_BSY) == SET) { }
GPIO_SetBits(GPIOA, GPIO_Pin_4);

if (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_CRCERR) != RESET)
{
  SPI_I2S_ClearFlag(SPI1, SPI_I2S_FLAG_CRCERR);
}

/* OVR 标志：读 DR 再读 SR */
(void)SPI_I2S_ReceiveData(SPI1);
(void)SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_OVR);

void SPI2_IRQHandler(void)
{
  if (SPI_I2S_GetITStatus(SPI2, SPI_I2S_IT_RXNE) != RESET)
  {
    rxBuf[rxIdx++] = SPI_I2S_ReceiveData(SPI2);   /* 读 DR 自动清 RXNE */
  }
  if (SPI_I2S_GetITStatus(SPI2, SPI_I2S_IT_TXE) != RESET)
  {
    if (txIdx < txLen)
      SPI_I2S_SendData(SPI2, txBuf[txIdx++]);
    else
      SPI_I2S_ITConfig(SPI2, SPI_I2S_IT_TXE, DISABLE);  /* 发完关 TXE，否则死循环 */
  }
}

/* 只清 CRCERR，其它标志请按下面的方式处理 */
if (SPI_I2S_GetITStatus(SPI1, SPI_I2S_IT_CRCERR) != RESET)
{
  SPI_I2S_ClearITPendingBit(SPI1, SPI_I2S_IT_CRCERR);
}

/* OVR 标志：先读 DR 再读 SR */
(void)SPI_I2S_ReceiveData(SPI1);
(void)SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_OVR);

/* MODF 标志：先读 SR 再写 CR1（SPI_Cmd 提供了写 CR1 的动作） */
(void)SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_MODF);
SPI_Cmd(SPI1, ENABLE);
